<?php
namespace Azula\SmsStudio;

final class M6Campaigns
{
    public function __construct(private M6Store $s,private ?AudienceSource $source){}
    public function listing(int $page=1,bool $trash=false):array
    {
        $page=max(1,$page);$t=$this->s->table('campaigns');$m=$this->s->table('campaign_meta');$q=$this->s->table('schedules');
        $where="COALESCE(m.purpose,'campaign')='campaign' AND ".($trash?'COALESCE(m.trashed_at,0)>0':'COALESCE(m.trashed_at,0)=0');
        $rows=$this->s->rows("SELECT c.*,s.state schedule_state,s.start_at scheduled_at,COALESCE(m.trashed_at,0) trashed_at FROM $t c LEFT JOIN $m m ON m.campaign_id=c.id LEFT JOIN $q s ON s.campaign_id=c.id WHERE $where ORDER BY c.id DESC LIMIT 26 OFFSET %d",($page-1)*25);$more=count($rows)>25;$rows=array_slice($rows,0,25);$out=[];
        foreach($rows as $c){$id=(int)$c['id'];$attempted=(bool)$this->s->row('SELECT * FROM '.$this->s->table('attempts').' WHERE campaign_id=%d LIMIT 1',$id);$p=$this->s->latestPlan($id);try{$segment=$this->source->segment((int)$c['segment_id']);}catch(\Throwable $e){$segment=['name'=>'Saved segment #'.$c['segment_id'].' (source unavailable)'];}$cancelled=CampaignLifecycle::cancelled($this->s->database,$c);$frozen=(bool)$c['transmission_intent']||$attempted;$active=$p&&!in_array($p['state'],['invalidated','canceled','m9_preparing','m9_ready','m9_complete','m9_blocked','m9_cancelled'],true);$trashed=(int)$c['trashed_at']>0;
            $actions=$trashed?['restore']:['view','duplicate'];if(!$trashed&&!$frozen&&!$cancelled&&!$active)$actions=array_merge($actions,['edit','reschedule']);if(!$trashed&&!$cancelled&&!in_array($c['state'],['canceled','submitted','controlled_accepted'],true)&&($c['scheduled_at']||$p))$actions[]='cancel';if(!$trashed&&!$cancelled&&!$attempted&&!$frozen)$actions[]='trash';
            $display=$p&&!in_array($p['state'],['invalidated','canceled'],true)?$p['state']:($c['state']==='canceled'?'canceled':($c['schedule_state']&&!in_array($c['schedule_state'],['canceled','missed'],true)?$c['schedule_state']:$c['state']));
            $execution=RC1Status::modern()?RC1Status::campaign($this->s,$id):null;if($execution){if(!empty($execution['can_reschedule'])&&!$cancelled&&!$frozen&&!$trashed&&!in_array('reschedule',$actions,true))$actions[]='reschedule';if(empty($execution['can_reschedule'])&&$execution['mode']!=='dry'&&in_array($execution['state'],['blocked','paused','authorized'],true))$actions=array_values(array_diff($actions,['edit','reschedule']));$display=$cancelled&&!$attempted?'Cancelled':$execution['label'];if($execution['scheduled'])$c['scheduled_at']=$execution['start'];}
            $out[]=['id'=>$id,'name'=>$c['name'],'segment_id'=>(int)$c['segment_id'],'segment'=>$segment['name'],'created'=>(int)$c['created_at'],'scheduled'=>$c['scheduled_at']?CairoTime::label((int)$c['scheduled_at']):null,'state'=>$trashed?'trashed':$display,'actions'=>$actions];
        }return ['rows'=>$out,'page'=>$page,'more'=>$more];
    }
    private function revision(array $c,string $event,array $extra=[]):void
    {
        $id=(int)$c['id'];$revision=(int)$c['revision']+1;$this->s->update('campaigns',['revision'=>$revision,'review_hash'=>null,'approval_hash'=>null]+$extra,['id'=>$id]);$this->s->insert('revisions',['campaign_id'=>$id,'revision'=>$revision,'binding_json'=>json_encode(['operation'=>$event,'operational'=>false],JSON_THROW_ON_ERROR),'created_at'=>time()]);$this->s->audit($id,$event,['revision'=>$revision]);
    }
    public function action(int $id,string $action,string $name=''):array
    {
        $r=$this->s->campaigns->m2->lock(-$id,function()use($id,$action,$name){return $this->s->database->transaction(function()use($id,$action,$name){
            $c=$this->s->row('SELECT * FROM '.$this->s->table('campaigns').' WHERE id=%d FOR UPDATE',$id);if(!$c)throw new ControlledTestException('Campaign not found.');$meta=$this->s->meta($id,true);$frozen=(bool)$c['transmission_intent'];
            if($action==='restore'){if(CampaignLifecycle::cancelled($this->s->database,$c))throw new ControlledTestException('Cancelled campaigns cannot be restored as drafts. Duplicate the campaign instead.');if(!$meta['trashed_at'])throw new ControlledTestException('Campaign is not in Trash.');$this->s->update('campaign_meta',['trashed_at'=>0,'updated_at'=>time()],['campaign_id'=>$id]);$this->revision($c,'campaign_restored',['state'=>'draft','audience_id'=>null]);return ['id'=>$id];}
            if($meta['trashed_at'])throw new ControlledTestException('Restore the campaign first.');
            if($action==='duplicate'){if(M10::modern()){$copyToken=substr($this->s->crypto->digest(['copy_source'=>$id,'revision'=>(int)$c['revision'],'actor'=>get_current_user_id()]),0,32);$known=$this->s->row('SELECT id FROM '.$this->s->table('campaigns').' WHERE draft_token=%s',hash('sha256',$copyToken));if($known)return ['id'=>(int)$known['id'],'replayed'=>true];}$new=(M10::modern()?$this->s->campaigns->m2->draft($copyToken,(int)$c['segment_id'],'Copy of '.$c['name']):$this->s->campaigns->m2->store()->createCampaign('Copy of '.$c['name'],(int)$c['segment_id'],null,CairoTime::ZONE));$message=$this->s->campaigns->m2->message($c);$message=(new M6Links($this->s))->expand($id,$message);if($message!=='')$this->s->campaigns->m2->saveMessage($new,$message,1);$this->s->meta($new,true);$this->s->audit($new,'campaign_duplicated',['source_campaign'=>$id]);return ['id'=>$new];}
            if($action==='cancel'){
                if(M9Schema::modern())foreach($this->s->rows('SELECT r.id,r.plan_id FROM '.$this->s->table('bulk_runs')." r INNER JOIN ".$this->s->table('sendplans')." p ON p.id=r.plan_id WHERE p.campaign_id=%d AND r.state NOT IN ('complete','cancelled')",$id) as $run){$this->s->update('bulk_runs',['state'=>'cancelled','next_check'=>0,'last_progress'=>time()],['id'=>$run['id']]);$this->s->update('sendplans',['state'=>'m9_cancelled','next_check'=>0,'updated_at'=>time()],['id'=>$run['plan_id']]);}
                $plans=$this->s->table('sendplans');$runs=$this->s->table('bulk_runs');if(M9Schema::modern())$this->s->query("UPDATE $plans SET state='canceled',next_check=0,updated_at=%d WHERE campaign_id=%d AND state NOT IN ('submitted','unknown','canceled','invalidated','m9_complete','m9_cancelled') AND NOT EXISTS (SELECT id FROM $runs WHERE plan_id=$plans.id)",time(),$id);else $this->s->query("UPDATE $plans SET state='canceled',next_check=0,updated_at=%d WHERE campaign_id=%d AND state NOT IN ('submitted','unknown','canceled','invalidated')",time(),$id);
                $this->s->query('UPDATE '.$this->s->table('send_items')." SET state='canceled' WHERE campaign_id=%d AND state='pending'",$id);$this->s->update('schedules',['state'=>'canceled','approval_hash'=>null,'approval_payload'=>null,'next_check'=>0],['campaign_id'=>$id]);$this->s->campaigns->cancelQueue($id);$this->s->update('campaigns',['state'=>'canceled','approval_hash'=>null],['id'=>$id]);$this->s->audit($id,'campaign_canceled');return ['id'=>$id];
            }
            if(CampaignLifecycle::cancelled($this->s->database,$c))throw new ControlledTestException('This campaign is cancelled. View its history or duplicate it; its original identity remains terminal.');if($frozen)throw new ControlledTestException('A submitted or uncertain campaign is frozen. Its history cannot be edited or trashed.');
            if($action==='trash'){if($this->s->row('SELECT * FROM '.$this->s->table('attempts').' WHERE campaign_id=%d LIMIT 1',$id))throw new ControlledTestException('Attempt history must be preserved outside Trash.');$this->s->invalidate($id,'trashed');$this->s->campaigns->invalidate($id,'trashed');$this->s->update('schedules',['state'=>'canceled','next_check'=>0],['campaign_id'=>$id]);$this->s->campaigns->m2->supersede($id);$this->s->update('campaign_meta',['trashed_at'=>time(),'updated_at'=>time()],['campaign_id'=>$id]);$this->revision($c,'campaign_trashed',['state'=>'trashed']);return ['id'=>$id];}
            if($action==='rename'){$name=trim($name);if($name===''||strlen($name)>190||preg_match('/[\x00-\x1f\x7f]/',$name))throw new ControlledTestException('Enter a campaign name up to 190 bytes.');$this->s->invalidate($id,'name_changed');$this->s->campaigns->invalidate($id,'name_changed');$this->revision($c,'campaign_renamed',['name'=>$name,'state'=>'draft']);return ['id'=>$id];}
            throw new ControlledTestException('Unsupported campaign action.');
        });});if(!$r)throw new ControlledTestException('Campaign is busy. Try again after refreshing its status.');return $r;
    }
}
